class Solution {
public:
    long long maximumPoints(vector<int>& enemyEnergies, int currentEnergy) {
        int min_e = *min_element(enemyEnergies.begin(), enemyEnergies.end());
        if (currentEnergy < min_e) return 0;
        long long total_energy = currentEnergy;
        for (int e : enemyEnergies) total_energy += e;
        total_energy -= min_e;
        return total_energy / min_e;
    }
};

class Solution {
    public long maximumPoints(int[] enemyEnergies, int currentEnergy) {
        int minE = Integer.MAX_VALUE;
        long sum = 0;
        for (int e : enemyEnergies) {
            if (e < minE) minE = e;
            sum += e;
        }
        if (currentEnergy < minE) return 0;
        long totalEnergy = (long) currentEnergy + sum - minE;
        return totalEnergy / minE;
    }
}

var maximumPoints = function(enemyEnergies, currentEnergy) {
    let minE = Infinity;
